-- Aug-2026 issues 20 & 21 — the evaluation report needs real PER-EVALUATOR,
-- PER-PARAMETER human scores, not just the roll-up totals seeded in 0008.
--
-- Issue 20: "additional columns keep adding as the deck passes hands" — each
-- evaluator below becomes a column on the report.
-- Issue 21: the hierarchy (program associate → jury → program manager) is only
-- observable once more than one level has scored the same deck, so each deck
-- here carries scores from all three levels.
--
-- Values are derived from the evaluator's own weighted total already in
-- `evaluations` (0008), spread deterministically across the parameters, so the
-- per-parameter detail agrees with the totals the reports already show.

DELETE FROM scores WHERE evaluator_kind = 'human' AND deck_id IN (
  'inc_deck_insureflow','inc_deck_greengrid','inc_deck_finstack',
  'inc_deck_wealthosi','inc_deck_greenroute'
);


-- Keep the roll-up in `evaluations` in agreement with the per-parameter detail
-- above for the two decks 0008 did not cover, so the Jury Pipeline's "Jury
-- score" and "Avg. score" columns match the report a reviewer opens from them.
DELETE FROM evaluations
WHERE evaluator_id IS NOT NULL AND deck_id IN ('inc_deck_wealthosi', 'inc_deck_greenroute');

SELECT 'ev_seed_' || s.deck_id || '_' || s.evaluator_id,
       s.deck_id,
       s.evaluator_id,
       ROUND(SUM(s.value * p.weight) / SUM(p.weight), 1),
       'advanced',
       'Evaluation submitted',
       '2026-08-21T07:00:00Z'
FROM scores s
JOIN parameters p ON p.id = s.parameter_id
WHERE s.evaluator_kind = 'human'
  AND p.informational = 0
  AND s.deck_id IN ('inc_deck_wealthosi', 'inc_deck_greenroute')
GROUP BY s.deck_id, s.evaluator_id;
